function getKustomerTranslation(key, lang) {
  if (kustomerTranslations[lang] && kustomerTranslations[lang][key]) {
    return kustomerTranslations[lang][key];
  }
  if (kustomerTranslations.en && kustomerTranslations.en[key]) {
    return kustomerTranslations.en[key];
  }
  return null;
}

function applyKustomerTranslations(lang) {
  console.log(`🔥 Applying kustomer translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.kustomer.') || key.startsWith('review.common.'))) {
      const translation = getKustomerTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} kustomer translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyKustomerTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyKustomerTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyKustomerTranslations(currentLang);
}

console.log('✅ kustomer i18n loaded');
